sp_widget.client_script:
function($rootScope,$scope) {
	/* widget controller */
	const c = this;

	// Event to emit on list item click
	c.selectItem = (i) => {
		const id = c.data.notes[i].sys_id;
		$rootScope.$emit("selectNote", id);
	}

	// Update controller data in response to a note being edited
	$rootScope.$on('editedNote', (event,data) => {
		c.data.notes.map((note) => {
			if (note.sys_id == data.sys_id) {
				note.title = data.title;
				note.note = data.body.slice(0,50) + "...";
			}
		})
	});
}

sp_widget.script:
(() => {
	// Populate data.notes with objects corresponding to the user's notes
	data.notes = [];
	var noteGR = new GlideRecord("x_snc_createnotes_note");
	noteGR.addQuery("user", gs.getUser().getID());
	noteGR.orderByDesc("sys_created_on");
	noteGR.query();

	while (noteGR.next()) {
		var noteObj = {};
		$sp.getRecordDisplayValues(noteObj, noteGR, "number,title,sys_id");
		noteObj.note = noteGR.getValue("note").slice(0,50) + "...";
		data.notes.push(noteObj);
	}
})();
